UPDATE fin_ex_chat_message_t
SET content = #{content},
    run_id = COALESCE(#{runId}, run_id),
    metadata_json = #{metadataJson}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND id = #{id}
  AND role = 'assistant'

