mapper.select:
WITH RECURSIVE active_path AS (
    SELECT m.*
    FROM fin_ex_chat_message_t m
    JOIN fin_ex_chat_session_t s ON s.id = m.session_id
    WHERE m.tenant_id = #{tenantId}
      AND m.user_id = #{userId}
      AND m.session_id = #{sessionId}
      AND m.id = COALESCE(#{leafMessageId}, s.current_leaf_message_id)
    UNION ALL
    SELECT p.*
    FROM fin_ex_chat_message_t p
    JOIN active_path child ON child.parent_message_id = p.id
    WHERE p.tenant_id = #{tenantId}
      AND p.user_id = #{userId}
      AND p.session_id = #{sessionId}
)
SELECT * FROM active_path
ORDER BY tree_depth DESC, node_order DESC
LIMIT #{limit}

WITH RECURSIVE active_path AS (
    SELECT m.*
    FROM fin_ex_chat_message_t m
    JOIN fin_ex_chat_session_t s ON s.id = m.session_id
    WHERE m.tenant_id = #{tenantId}
      AND m.user_id = #{userId}
      AND m.session_id = #{sessionId}
      AND m.id = COALESCE(#{leafMessageId}, s.current_leaf_message_id)
    UNION ALL
    SELECT p.*
    FROM fin_ex_chat_message_t p
    JOIN active_path child ON child.parent_message_id = p.id
    WHERE p.tenant_id = #{tenantId}
      AND p.user_id = #{userId}
      AND p.session_id = #{sessionId}
)
SELECT * FROM active_path
ORDER BY tree_depth ASC, node_order ASC

SELECT *
FROM fin_ex_chat_message_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND role IN ('user', 'assistant')
ORDER BY node_order ASC, created_at ASC, id ASC

SELECT * FROM ( SELECT m.*, ROW_NUMBER() OVER ( PARTITION BY m.session_id ORDER BY m.node_order ASC, m.created_at ASC, m.id ASC ) AS rn FROM fin_ex_chat_message_t m JOIN fin_ex_chat_session_t s ON s.id = m.session_id AND s.tenant_id = m.tenant_id AND s.user_id = m.user_id WHERE m.tenant_id = #{tenantId} AND m.user_id = #{userId} AND m.role = 'assistant' AND s.status <> 'DELETED'
AND m.session_id IN
#{sessionId}
AND 1 = 0
) ranked WHERE ranked.rn = 1

